import { createWhichCommand, createWhichCommands, whichCommands, type WhichCommandsOptions, type WhichLimits, type CommandDefinition, type VirtualShellPlugin } from 'virtual-bash';
import { createWhichCommand as subCommand, createWhichCommands as subCommands, whichCommands as subPlugin, type WhichCommandsOptions as SubOptions, type WhichLimits as SubLimits } from 'virtual-bash/commands/which';
const options: WhichCommandsOptions = { replace: true, limits: { maxProbes: 1 } };
const subOptions: SubOptions = options;
declare const limits: WhichLimits; const subLimits: SubLimits = limits;
const factories: [typeof createWhichCommand, typeof createWhichCommands, typeof whichCommands] = [subCommand, subCommands, subPlugin];
const definition: CommandDefinition = createWhichCommand(subOptions);
const definitions: readonly CommandDefinition[] = createWhichCommands(options);
const plugin: VirtualShellPlugin = whichCommands({ limits: subLimits });
void factories; void definition; void definitions; void plugin;
// @ts-expect-error public declared collection is readonly
createWhichCommands().push(definition);

import { agentCommands, createAgentCommands, type AgentCommandsOptions, type WhichCommandsOptions } from 'virtual-bash';
type Equal<Left, Right> = (<Value>() => Value extends Left ? 1 : 2) extends (<Value>() => Value extends Right ? 1 : 2) ? true : false;
type Expect<Value extends true> = Value;
type ExactWhich = Expect<Equal<NonNullable<AgentCommandsOptions['which']>, Omit<WhichCommandsOptions, 'replace'>>>;
const options: AgentCommandsOptions = { replace: true, which: { limits: { maxOutputBytes: 8 } } };
agentCommands(options); createAgentCommands(options); const exact: ExactWhich = true; void exact;
// @ts-expect-error aggregate family cannot choose replacement policy
agentCommands({ which: { replace: true } });
// @ts-expect-error aggregate family cannot choose replacement policy
createAgentCommands({ which: { replace: false } });
// @ts-expect-error readonly aggregate option
options.which = {};
// @ts-expect-error no invented host fallback option
agentCommands({ which: { hostFallback: true } });

import { createWhichCommand, agentCommands, type WhichLimits } from 'virtual-bash';
import { whichCommands } from 'virtual-bash/commands/which';
const limits: WhichLimits = { maxArguments: 4096, maxArgumentBytes: 65536, maxPathEnvBytes: 65536, maxPathComponents: 4096, maxPathBytes: 16384, maxProbes: 65536, maxOutputBytes: 8388608 };
createWhichCommand({ limits }); whichCommands({ limits: { maxPathBytes: 32 } }); agentCommands({ which: { limits: { maxOutputBytes: 1 } } });
// @ts-expect-error readonly limit
limits.maxProbes = 1;
// @ts-expect-error numeric limit required
agentCommands({ which: { limits: { maxProbes: '1' } } });
// @ts-expect-error unknown command limit
whichCommands({ limits: { maxCommands: 1 } });

import { createWhichCommand, type CommandContext, type CommandResult, type ByteSink } from 'virtual-bash';
import { createWhichCommand as subCommand } from 'virtual-bash/commands/which';
declare const context: CommandContext; declare const sink: ByteSink;
const result: CommandResult | Promise<CommandResult> = createWhichCommand().execute(context);
const other: CommandResult | Promise<CommandResult> = subCommand().execute(context);
void result; void other;
// @ts-expect-error command context signal remains readonly
context.signal = new AbortController().signal;
// @ts-expect-error stdout is byte-oriented
sink.write('not bytes');
